<section class="container page-section">
	<div class="page-heading"><div><p class="eyebrow">Area keluarga</p><h1 class="h2">Akun anak</h1><p class="text-secondary">Kelola akun anak yang terhubung dengan akunmu.</p></div><a class="btn btn-primary rounded-pill px-4" href="<?php echo site_url('keluarga/anak/tambah'); ?>"><i class="bi bi-plus-lg me-2" aria-hidden="true"></i>Tambah anak</a></div>
	<?php if ($children): ?><div class="row g-3"><?php foreach ($children as $child): $stage_labels = array('early_childhood' => 'Usia dini', 'primary' => 'Sekolah dasar', 'secondary' => 'Remaja'); ?><div class="col-md-6 col-lg-4"><article class="child-card"><span class="child-avatar" aria-hidden="true"><i class="bi bi-person-heart"></i></span><div class="flex-grow-1"><h2 class="h5 mb-1"><?php echo html_escape($child['display_name']); ?></h2><p class="small text-secondary mb-1">@<?php echo html_escape($child['username']); ?> · <?php echo (int)$child['completed_lessons']; ?> pelajaran selesai</p><?php echo form_open('keluarga/anak/'.$child['id'].'/kelompok', array('class' => 'd-flex align-items-center gap-2')); ?><label class="visually-hidden" for="stage-<?php echo (int)$child['id']; ?>">Kelompok belajar <?php echo html_escape($child['display_name']); ?></label><select class="form-select form-select-sm" name="learning_stage" id="stage-<?php echo (int)$child['id']; ?>"><?php if($child['learning_stage']==='unset'): ?><option value="" selected disabled>Pilih kelompok</option><?php endif; ?><?php foreach($stage_labels as $stage=>$label): ?><option value="<?php echo html_escape($stage); ?>" <?php echo $child['learning_stage']===$stage?'selected':''; ?>><?php echo html_escape($label); ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-primary" type="submit">Simpan</button><?php echo form_close(); ?></div><span class="badge text-bg-success">Aktif</span></article></div><?php endforeach; ?></div><?php else: ?><div class="empty-card"><span class="empty-icon"><i class="bi bi-people" aria-hidden="true"></i></span><h2 class="h4">Belum ada akun anak</h2><p class="text-secondary">Kamu dapat menambahkan akun untuk anak yang akan belajar.</p><a class="btn btn-primary rounded-pill px-4" href="<?php echo site_url('keluarga/anak/tambah'); ?>">Tambahkan akun anak</a></div><?php endif; ?>
